chrome.runtime.onInstalled.addListener(()=>{chrome.sidePanel.setPanelBehavior({openPanelOnActionClick:!0}).catch(e=>{console.error(`[Dexor Companion] Error setting side panel behavior:`,e)})}),chrome.action.onClicked.addListener(async e=>{if(e.windowId)try{await chrome.sidePanel.open({windowId:e.windowId})}catch(e){console.error(`[Dexor Companion] Could not open side panel:`,e)}});